function cleanMeta(r){r=isRecord(r)?r:{};const num=(v,mx=1e9)=>Math.floor(clampNumber(v,0,mx,0)),obj=o=>isRecord(o)?o:{};const med={},kr={},kills={},st={},nm={};
  for(const k in obj(r.med))if(/^[rkzdm][1-5]$/.test(k))med[k]=num(r.med[k],3);for(const k in obj(r.kr))if(/^[\w-]{1,40}$/.test(k)&&r.kr[k])kr[k]=1;
  for(const k in obj(r.kills))if(/^\w{1,30}$/.test(k))kills[k]=num(r.kills[k]);for(const k in obj(r.nm))if(/^\w{1,30}$/.test(k))nm[k]=num(r.nm[k]);const notes={};for(const k in obj(r.notes))if(/^\w{1,30}$/.test(k)&&r.notes[k])notes[k]=1;const endl={};for(const k in obj(r.endl))if(/^[1-5]$/.test(k))endl[k]=num(r.endl[k]);for(const k of ['kills','nights','wins','chals','parries','ash','winR','winK','winZ','winD','winM','time','nR','nK','nZ','nD','nM','tR','tK','tZ','tD','tM','hits','dmg','deaths'])st[k]=num(obj(r.st)[k]);const sku={};for(const k in obj(r.sku))if(/^[rkz]:\w{1,30}$/.test(k))sku[k]=num(r.sku[k]);
  const w=obj(r.wk),y=obj(r.dy),ss=v=>typeof v==='string'?v.slice(0,12):'';const sn=isRecord(r.sn)?(()=>{const o={};for(const k in r.sn)if(/^[aben]:[\w-]{1,40}$/.test(k))o[k]=1;return o})():null;return{v:1,sn,med,kr,kills,nm,sku,endl,notes,st,wk:{done:ss(w.done),key:ss(w.key),best:num(w.best)},dy:{done:ss(y.done),key:ss(y.key),best:num(y.best),streak:num(y.streak,9999),top:num(y.top,9999)},bst:(()=>{const o={};for(const k in obj(r.bst))if(/^(?:[1-5]|dg)$/.test(k)){const v=obj(r.bst[k]);o[k]={kills:num(v.kills),streak:num(v.streak),hit:num(v.hit),dmg:num(v.dmg),eli:num(v.eli)}}return o})()}}
const META=(()=>{try{return cleanMeta(JSON.parse(localStorage.getItem('pn_meta')||'{}'))}catch(e){return cleanMeta({})}})();
