function kronUnl(){const o=[];for(const k of KRON)if(META.kr[k[0]])o.push('a:'+k[0]);for(const t in META.kills)if(META.kills[t]>0&&t!=='glizzard'&&ENAME[t])o.push('b:'+t);for(const k in META.nm)if(META.nm[k]>0)o.push('e:'+k);for(const k in (META.notes||{}))o.push('n:'+k);return o}
function kronNew(){if(!META.sn){META.sn={};for(const k of kronUnl())META.sn[k]=1;saveMeta()}return kronUnl().filter(k=>!META.sn[k])}
