function kronCheck(x){const got=[];for(const [id,n,d,ash,v] of KRON){if(META.kr[id])continue;let ok=false;try{ok=!!v(x)}catch(e){quietErr('kron:'+id,e)}if(ok){META.kr[id]=1;EMB.e+=ash;got.push(n+' (+'+ash+')')}}
  for(const r of NAMED_ALL)if(META.nm[r.id]&&!META.kr['nm_'+r.id]){META.kr['nm_'+r.id]=1;EMB.e+=NAMED_ASH;got.push((EN?'Named elite: ':'Elita z imieniem: ')+r.n+' (+'+NAMED_ASH+')')}
  for(const t in META.kills)if(ENAME[t]&&META.kills[t]>=50&&!META.kr['b50_'+t]){META.kr['b50_'+t]=1;EMB.e+=10;got.push((EN?'Bestiary: ':'Bestiariusz: ')+ENAME[t]+' ×50 (+10)')}
  if(got.length){saveMeta();saveEmb()}return got}
// ---- end of night: medals, stats, weekly, chronicle (called from grantXp) ----
function metaAfterNight(won,surv){if(!S||S.dg)return '';const C=CH,c=charId(),st=META.st,out=[];if(S.endless){const tt=Math.floor(S.t||0),pr=META.endl[C]||0;if(tt>pr){META.endl[C]=tt;S.endlRec=1}S.endlPrev=pr}st.nights++;st.kills+=S.kills||0;st.parries+=S.parries||0;{const C1=c.toUpperCase(),tt=Math.round(S.t||0);st.time+=tt;st['n'+C1]++;st['t'+C1]+=tt;st.hits+=S.hitsT||0;st.dmg+=Math.round(S.dealt||0);if(!won&&pl&&pl.dead)st.deaths++;for(const k in S.sk||{})if(S.sk[k]>0&&SK[k])META.sku[c+':'+k]=(META.sku[c+':'+k]||0)+1}if(S.chal&&S.chal.done)st.chals++;
  if(won){st.wins++;st[{r:'winR',k:'winK',z:'winZ',d:'winD',m:'winM'}[c]]++;
    const tier=S.chal&&S.chal.done?((S.hitsT||0)<=10&&DIFFK!=='e'?3:2):1,old=medalOf(c,C);
    if(tier>old){let g=0;for(let t=old+1;t<=tier;t++)g+=MEDAL_ASH[t];META.med[c+C]=tier;EMB.e+=g;out.push((EN?'Medal: ':'Medal: ')+MEDAL_N[tier]+' (+'+g+(EN?' Ashes)':' Popiołów)'))}
    if(S.weekly&&META.wk.done!==S.weekly){META.wk.done=S.weekly;EMB.e+=60;out.push(EN?'Night of the Week: +60 Ashes':'Noc tygodnia: +60 Popiołów')}}
  if(S.weekly){if(META.wk.key!==S.weekly){META.wk.key=S.weekly;META.wk.best=0}META.wk.best=Math.max(META.wk.best,S.kills||0)}
  if(S.daily){const y=META.dy;if(won&&y.done!==S.daily){const yd=new Date();yd.setDate(yd.getDate()-1);y.streak=y.done===dayKey(yd)?y.streak+1:1;y.top=Math.max(y.top,y.streak);y.done=S.daily;EMB.e+=DAILY_ASH;out.push((EN?'Daily challenge: +':'Wyzwanie dnia: +')+DAILY_ASH+(EN?' Ashes · streak ':' Popiołów · seria ')+y.streak)}
    if(y.key!==S.daily){y.key=S.daily;y.best=0}y.best=Math.max(y.best,S.kills||0)}
  const got=kronCheck({won,C});if(got.length)out.push((EN?'Chronicle: ':'Kronika: ')+got.join(', '));saveMeta();saveEmb();return out.join('\n')}
function metaAsh(g){META.st.ash+=Math.max(0,g)}
function metaNamed(e){if(S&&S.train)return;if(e&&e.named)META.nm[e.named]=(META.nm[e.named]||0)+1}
function metaKill(e){if(S&&S.train)return;if(e&&e.type&&ENAME[e.type])META.kills[e.type]=(META.kills[e.type]||0)+1}
